"""Regenerate with: uv run --with pillow==12.1.0 <this script>."""

from pathlib import Path
from PIL import Image, __version__

assert __version__ == "12.1.0"
license_lines = (
    Path(__file__)
    .resolve()
    .parents[4]
    .joinpath("scripts/license-header-apache.txt")
    .read_text()
    .rstrip()
    .splitlines()
)
rows = [
    *(f"// {line}" if line else "//" for line in license_lines),
    "",
    "// Generated by ../testdata/generate_resampling_references.py using Pillow 12.1.0.",
    "",
    "pub const Case = struct { width: u32, height: u32, target_width: u32, target_height: u32, resample: u8, rgb: []const u8 };",
    "pub const cases = [_]Case{",
]
for w, h, tw, th in [(7, 5, 3, 2), (3, 2, 7, 5), (13, 11, 1, 1), (1, 7, 5, 3)]:
    pixels = bytes(
        v
        for y in range(h)
        for x in range(w)
        for v in (
            (x * 71 + y * 29) % 256,
            (x * 13 + y * 83) % 256,
            (x * 109 + y * 17) % 256,
        )
    )
    im = Image.frombytes("RGB", (w, h), pixels)
    for resample in (0, 2, 3):
        expected = im.resize((tw, th), resample=resample).tobytes()
        rows.append(
            f".{{ .width={w}, .height={h}, .target_width={tw}, .target_height={th}, .resample={resample}, .rgb=&.{{"
            + ",".join(map(str, expected))
            + "} },"
        )
rows.append("};\n")
Path(__file__).resolve().parents[1].joinpath(
    "src/resampling_reference_cases.zig"
).write_text("\n".join(rows))
